def _groupe(name, description, role=None, **perms):
    g = {'name': name, 'description': description, 'is_system': True,
         'allowed_menus': None, 'role': role, 'max_discount_rate': 0}
    g.update({f: False for f in PERM_FIELDS})
    g.update(perms)
    return g


def seed_groupes(apps, schema_editor):
    GroupePermissions = apps.get_model('api', 'GroupePermissions')
    Profile = apps.get_model('api', 'Profile')

    tout = {f: True for f in PERM_FIELDS}
    groupes = [
        _groupe('Pharmacien', 'Tous les droits.', role='PHARMACIEN', **tout,
                max_discount_rate=100),
        _groupe('Vendeur', 'Vente courante, sans droits sensibles.', role='VENDEUR',
                can_cash_out=True, can_view_cash_totals=True),
        _groupe('Caissier', 'Encaissement et validation des ventes.', role='CAISSIER',
                can_cash_out=True, can_validate_sales=True,
                can_view_cash_sessions=True, can_view_cash_totals=True),
        _groupe('Comptable', 'Consultation financière, aucun droit de vente.', role='COMPTABLE',
                can_view_cash_sessions=True, can_view_cash_totals=True),
        _groupe('Commandes', 'Gestion des commandes fournisseurs.', role=None,
                can_close_commande=True, can_delete_commande=True,
                can_manage_avoirs=True),
    ]
    by_role = {}
    for spec in groupes:
        role = spec.pop('role')
        groupe, _ = GroupePermissions.objects.get_or_create(
            name=spec['name'], defaults=spec)
        if role:
            by_role[role] = groupe

    # Affecter chaque profil au groupe de son rôle ; les droits actuels qui
    # diffèrent du groupe deviennent des dérogations (option 1 : préservation).
    fields = PERM_FIELDS + ['max_discount_rate']
    for profile in Profile.objects.select_related('groupe').iterator():
        groupe = by_role.get(profile.role)
        if groupe is None or profile.groupe_id == groupe.id:
            continue
        derog = {}
        for f in fields:
            current = getattr(profile, f)
            if current != getattr(groupe, f):
                # JSONField ne sérialise pas Decimal → float pour le taux
                derog[f] = float(current) if f == 'max_discount_rate' else current
        profile.groupe = groupe
        profile.derogations = derog
        profile.save(update_fields=['groupe', 'derogations'])


